#include <iostream>
#include <random>

int main()
{
    unsigned int seed{};
    int rolls{};
    std::cin >> seed >> rolls;

    std::mt19937 rng{ seed };
    std::uniform_int_distribution<int> die{ 1, 6 };

    int sixes{ 0 };
    std::cout << "Rolls:";
    for (int i{ 0 }; i < rolls; ++i)
    {
        const int roll{ die(rng) };
        std::cout << ' ' << roll;
        if (roll == 6)
        {
            ++sixes;
        }
    }
    std::cout << '\n';
    std::cout << "Sixes: " << sixes << '\n';
    return 0;
}
